def _apply_one_sync_member(parent, member, path, blobs):
    """Validate, stage and publish one member, all under its dir lock.

    The whole switch runs in one lock acquisition, so a concurrent
    save, load or append either observes the previous complete chain
    or the synced one; the directory never vanishes and no reader ever
    sees half a chain.
    """
    with _DirectoryChainLock(path):
