def racing_saver(path):
    try:
        while not stop:
            doc = cp.load_chain(path)
            # A save racing the publication either committed
            # on the old head (and is superseded by the
            # switch) or starts on the new chain after it;
            # either way the chain keeps loading and
            # verifying as one complete state.
            try:
                cp.save_chain(doc, path)
            except (OSError, FileNotFoundError):
                # The member directory is momentarily locked;
                # a contended rename surfaces as OSError to a
                # losing racer, which is allowed here.
                pass
            cp.load_chain(path)
    except BaseException as exc:  # noqa: BLE001
        errors.append(exc)

